const W=24,H=24;
function integral(data,w,h){
  const stride=w+1, sums=new Float64Array((h+1)*stride), squares=new Float64Array((h+1)*stride);
  for(let y=1;y<=h;y++){
    let sr=0,qr=0;
    const prev=(y-1)*stride,here=y*stride;
    for(let x=1;x<=w;x++){
      const p=data[(y-1)*w+x-1];sr+=p;qr+=p*p;
      sums[here+x]=sums[prev+x]+sr;
      squares[here+x]=squares[prev+x]+qr;
    }
  }
  return [sums,squares,stride];
}
function rectSum(a,stride,x,y,w,h){
 const p=y*stride+x,q=p+w,r=p+h*stride,s=r+w;
 return a[s]+a[p]-a[q]-a[r];
}
function grayScaled(source,w,h){
 const c=document.createElement('canvas');c.width=w;c.height=h;
 const g=c.getContext('2d',{willReadFrequently:true});
 g.drawImage(source,0,0,w,h);
 const p=g.getImageData(0,0,w,h).data;
 const out=new Uint8Array(w*h);
 for(let i=0,j=0;i<p.length;i+=4,j++)out[j]=Math.round(p[i]*.299+p[i+1]*.587+p[i+2]*.114);
 c.width=0;c.height=0;
 return out;
}
function evalWindow(sums,squares,stride,x,y){
 const invArea=1/(22*22);
 const mean=rectSum(sums,stride,x+1,y+1,22,22)*invArea;
 const variance=rectSum(squares,stride,x+1,y+1,22,22)*invArea-mean*mean;
 const norm=variance>1?Math.sqrt(variance):1;
 for(let i=0;i<model.stages.length;i++){
   const stage=model.stages[i];let score=0;
   for(let j=0;j<stage[1].length;j++){
     const n=stage[1][j],rects=model.features[n[0]];let f=0;
     for(let k=0;k<rects.length;k++){
       const r=rects[k];f+=r[4]*rectSum(sums,stride,x+r[0],y+r[1],r[2],r[3]);
     }
     // Normalize the Haar sum to the detector reference window area.
     score+=(f*invArea<n[1]*norm)?n[2]:n[3];
   }
   if(score<stage[0])return false;
 }
 return true;
}
function groupCandidates(rects){
 const groups=[];
 for(const r of rects.sort((a,b)=>b.width-a.width)){
   let assigned=false;
   for(const g of groups){
     const centerA=[r.x+r.width/2,r.y+r.height/2],centerB=[g.x+g.width/2,g.y+g.height/2];
     const d=Math.hypot(centerA[0]-centerB[0],centerA[1]-centerB[1]);
     const size=Math.max(r.width,g.width);
     if(d<size*.29 && Math.abs(r.width-g.width)<size*.34){
       const n=g.count;
       g.x=(g.x*n+r.x)/(n+1);g.y=(g.y*n+r.y)/(n+1);g.width=(g.width*n+r.width)/(n+1);g.height=(g.height*n+r.height)/(n+1);
       g.count++;assigned=true;break;
     }
   }
   if(!assigned)groups.push({...r,count:1});
 }
 return groups.filter(g=>g.count>=3).sort((a,b)=>b.count-a.count);
}
async function detect(source){
 const sw=source.naturalWidth||source.videoWidth||source.width,sh=source.naturalHeight||source.videoHeight||source.height;
 if(!sw||!sh) return [];
 const resize=Math.min(1,500/Math.max(sw,sh));
 const ww=Math.max(24,Math.round(sw*resize)),hh=Math.max(24,Math.round(sh*resize));
 const base=grayScaled(source,ww,hh);
 // Construct the image pyramid on the CPU to avoid downloading any model runtime.
 const results=[];
 let scale=1;
 for(let level=0;level<19;level++){
   const w=Math.round(ww/scale),h=Math.round(hh/scale);
   if(w<24||h<24)break;
   const gray=level===0?base:resizeGray(base,ww,hh,w,h);
   const [sums,squares,stride]=integral(gray,w,h);
   const step=(level<3?3:2);
   for(let y=0;y<=h-H;y+=step){
     for(let x=0;x<=w-W;x+=step){
       if(evalWindow(sums,squares,stride,x,y)){
         results.push({x:x*scale/resize,y:y*scale/resize,width:W*scale/resize,height:H*scale/resize});
       }
     }
   }
   scale*=1.19;
 }
 return groupCandidates(results).map(g=>({x:g.x,y:g.y,width:g.width,height:g.height,score:g.count}));
}
function resizeGray(src,sw,sh,w,h){
 const dest=new Uint8Array(w*h);
 for(let y=0;y<h;y++){
   const sy=(y+.5)*sh/h-.5;
   const y0=Math.max(0,Math.min(sh-1,Math.floor(sy))),y1=Math.min(sh-1,y0+1),wy=Math.max(0,Math.min(1,sy-y0));
   for(let x=0;x<w;x++){
     const sx=(x+.5)*sw/w-.5;
     const x0=Math.max(0,Math.min(sw-1,Math.floor(sx))),x1=Math.min(sw-1,x0+1),wx=Math.max(0,Math.min(1,sx-x0));
     dest[y*w+x]=Math.round((src[y0*sw+x0]*(1-wx)+src[y0*sw+x1]*wx)*(1-wy)+(src[y1*sw+x0]*(1-wx)+src[y1*sw+x1]*wx)*wy);
   }
 }
 return dest;
}
